```javascript
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const disposables = [];
  const timelines = [];
  let animFrameId = null;
  let settleTimeline = null;

  const palette = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const PLATE_W = 1.9;
  const PLATE_H = 1.2;
  const PITCH = 1.5;
  const COL_X = 0.9;
  const NUM = 6;
  const BEVEL = 0.03;

  let texture = null;
  try {
    texture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
    texture.colorSpace = THREE.SRGBColorSpace;
    disposables.push(texture);
  } catch (e) {
    console.warn('Image load failed:', e);
  }

  const matPlate = new THREE.MeshStandardMaterial({
    map: texture,
    roughness: 0.6,
    metalness: 0.1,
    clearcoat: 0.1,
  });
  disposables.push(matPlate);

  const matBevel = new THREE.MeshStandardMaterial({
    color: new THREE.Color(palette.ink),
    roughness: 0.5,
    metalness: 0.5,
  });
  disposables.push(matBevel);

  const matAccent = new THREE.MeshStandardMaterial({
    color: new THREE.Color(palette.accent),
    emissive: new THREE.Color(palette.accent),
    emissiveIntensity: 1.4,
    roughness: 0.4,
    metalness: 0.6,
  });
  disposables.push(matAccent);

  const platesGrp = new THREE.Group();
  const plates = [];

  for (let i = 0; i < NUM; i++) {
    const pg = new THREE.Group();

    // Main image surface
    const sg = new THREE.PlaneGeometry(PLATE_W, PLATE_H);
    disposables.push(sg);
    const sm = new THREE.Mesh(sg, matPlate);
    sm.position.z = 0.01;
    pg.add(sm);

    // Bevel top
    const tbg = new THREE.PlaneGeometry(PLATE_W + 2 * BEVEL, BEVEL);
    disposables.push(tbg);
    const tb = new THREE.Mesh(tbg, matBevel);
    tb.position.set(0, PLATE_H / 2 + BEVEL / 2, 0.005);
    pg.add(tb);

    // Bevel bottom
    const bbg = new THREE.PlaneGeometry(PLATE_W + 2 * BEVEL, BEVEL);
    disposables.push(bbg);
    const bb = new THREE.Mesh(bbg, matBevel);
    bb.position.set(0, -PLATE_H / 2 - BEVEL / 2, 0.005);
    pg.add(bb);

    // Bevel left
    const lbg = new THREE.PlaneGeometry(BEVEL, PLATE_H);
    disposables.push(lbg);
    const lb = new THREE.Mesh(lbg, matBevel);
    lb.position.set(-PLATE_W / 2 - BEVEL / 2, 0, 0.005);
    pg.add(lb);

    // Bevel right
    const rbg = new THREE.PlaneGeometry(BEVEL, PLATE_H);
    disposables.push(rbg);
    const rb = new THREE.Mesh(rbg, matBevel);
    rb.position.set(PLATE_W / 2 + BEVEL / 2, 0, 0.005);
    pg.add(rb);

    // Accent strip (left edge, emissive)
    const ag = new THREE.PlaneGeometry(BEVEL, PLATE_H + 2 * BEVEL);
    disposables.push(ag);
    const am = new THREE.Mesh(ag, matAccent);
    am.position.set(-PLATE_W / 2 - BEVEL - BEVEL / 2, 0, 0.01);
    pg.add(am);

    pg.position.set(COL_X, -i * PITCH, 0);
    plates.push(pg);
    platesGrp.add(pg);
  }

  group.add(platesGrp);

  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  const captionObjs = [];

  // Pinned headline
  if (ctx.fontAtlas) {
    try {
      const hl = ctx.fontAtlas.createText('Inside the atelier', {
        fontSize: 0.62,
        fontWeight: 600,
        family: 'Lora',
        color: new THREE.Color(palette.paper),
      });
      hl.position.set(-1.6, 1.9, 0.02);
      group.add(hl);
    } catch (e) {
      console.warn('Headline failed:', e);
    }
  }

  // Captions (one per plate)
  for (let i = 0; i < captions.length; i++) {
    try {
      const cap = ctx.fontAtlas.createText(captions[i], {
        fontSize: 0.09,
        fontWeight: 400,
        family: 'JetBrains Mono',
        color: new THREE.Color(palette.paper),
      });
      const by = -i * PITCH + 0.3;
      cap.position.set(-1.6, by, 0.02);
      cap.userData.idx = i;
      cap.userData.baseY = by;
      captionObjs.push(cap);
      group.add(cap);
    } catch (e) {
      console.warn('Caption failed:', e);
    }
  }

  const scroll = {
    y: 0,
    vel: 0,
    active: false,
  };

  const updatePositions = () => {
    for (let i = 0; i < plates.length; i++) {
      const p = plates[i];
      p.position.y = -i * PITCH + scroll.y;

      const d = Math.abs(p.position.y);
      const focus = d < 0.75 ? 1 + (1 - d / 0.75) * 0.06 : 1;
      p.scale.set(focus, focus, focus);
    }

    for (const c of captionObjs) {
      c.position.y = c.userData.baseY + scroll.y;
      const d = Math.abs(c.position.y);
      const op = Math.max(0, Math.min(1, 1 - d / 1.5));
      if (c.children[0]?.material) {
        c.children[0].material.opacity = op;
      }
    }
  };

  const snapToPlate = () => {
    const nearest = Math.round(scroll.y / PITCH) * PITCH;
    if (settleTimeline) settleTimeline.kill();
    settleTimeline = gsap.to(scroll, {
      y: nearest,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      onUpdate: () => {
        updatePositions();
      },
    });
    timelines.push(settleTimeline);
  };

  const updateFrame = () => {
    if (!scroll.active && Math.abs(scroll.vel) > 0.001) {
      scroll.vel *= 1 - 0.12;
    }

    const keep = scroll.active || Math.abs(scroll.vel) > 0.001;

    if (keep) {
      scroll.y += scroll.vel;

      const bound = (NUM * PITCH) / 2;
      while (scroll.y > bound) scroll.y -= NUM * PITCH;
      while (scroll.y < -bound) scroll.y += NUM * PITCH;

      updatePositions();

      animFrameId = requestAnimationFrame(updateFrame);
    } else {
      animFrameId = null;
      snapToPlate();
    }
  };

  group.userData.handlers = {
    onScroll(e) {
      e.preventDefault?.();
      if (settleTimeline) settleTimeline.kill();
      scroll.vel = e.deltaY * 0.01;
      scroll.active = true;
      if (!animFrameId) updateFrame();
      setTimeout(() => {
        scroll.active = false;
      }, 150);
    },
  };

  // Apply fly-through cinematic primitive
  if (config.cinematicPrimitives?.length && ctx.primitives['fly-through']) {
    const ft = config.cinematicPrimitives.find((p) => p.name === 'fly-through');
    if (ft) {
      ctx.primitives['fly-through'](group, ft.params || { depthUnits: 2.5 });
    }
  }

  group.userData.cleanup = () => {
    if (animFrameId) cancelAnimationFrame(animFrameId);
    timelines.forEach((t) => t.kill());
    if (settleTimeline) settleTimeline.kill();
    disposables.forEach((d) => d.dispose());
  };

  return group;
}
